    ok &= QuadCount(16) == 4 && QuadCount(7) == 1 && QuadCount(3) == 0 && QuadCount(-5) == -1;
    ok &= Walk(12, &c, &s) == 3 && c == 0xC0 && s == 0x30;
    ok &= Walk(2, &c, &s) == 0 && c == 0;
